command:
$ErrorActionPreference = 'Stop'
$forgeRoot = (Get-Location).Path
& '.forge-codex/instructions/scripts/Verify-Ledger.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoPython.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoAttribution.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-McpParity.ps1' -WorkspaceRoot $forgeRoot -ActualToolSnapshot (Join-Path $forgeRoot 'tests/fixtures/Mcp/mcp-tools-semantic-golden.json')
$forgeEvidencePath = Join-Path $forgeRoot '.forge-codex/state/evidence/P14/stdio-serve-primary-fallback-snapshot-checkpoint.json'
$forgeEvidence = Get-Content -Raw -LiteralPath $forgeEvidencePath | ConvertFrom-Json
if ($forgeEvidence.status -ne 'passed' -or $forgeEvidence.gate_status -ne 'open' -or $forgeEvidence.measured_result.tool_descriptors_per_role -ne 53) { throw 'P14 stdio checkpoint status or tool count is invalid.' }
$forgeCommands = @($forgeEvidence.build_command_records + $forgeEvidence.test_command_records | Sort-Object -Unique)
foreach ($forgeRecordRelative in $forgeCommands) {
  $forgeRecordPath = Join-Path $forgeRoot $forgeRecordRelative
  if (-not (Test-Path -LiteralPath $forgeRecordPath -PathType Leaf)) { throw "Missing command record: $forgeRecordRelative" }
  $forgeRecord = Get-Content -Raw -LiteralPath $forgeRecordPath | ConvertFrom-Json
  foreach ($forgeStreamName in @('stdout','stderr')) {
    $forgeStreamRelative = [string]$forgeRecord.$forgeStreamName
    $forgeStreamPath = Join-Path $forgeRoot $forgeStreamRelative
    if (-not (Test-Path -LiteralPath $forgeStreamPath -PathType Leaf)) { throw "Missing command stream: $forgeStreamRelative" }
    $forgeExpectedHash = [string]$forgeRecord."${forgeStreamName}_sha256"
    $forgeActualHash = (Get-FileHash -LiteralPath $forgeStreamPath -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($forgeActualHash -ne $forgeExpectedHash) { throw "Command stream hash mismatch: $forgeStreamRelative" }
  }
}
foreach ($forgeFinalRecordRelative in @('.forge-codex/state/commands/20260827T080544923Z-8ead2fbf.json','.forge-codex/state/commands/20260827T080627818Z-6a419ea5.json','.forge-codex/state/commands/20260827T080837982Z-d54ec62a.json')) {
  $forgeFinalRecord = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot $forgeFinalRecordRelative) | ConvertFrom-Json
  if ($forgeFinalRecord.exit_code -ne 0 -or $forgeFinalRecord.timed_out) { throw "A designated final command did not pass: $forgeFinalRecordRelative" }
}
$forgeExpectedFailure = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot '.forge-codex/state/commands/20260827T075424142Z-d322862c.json') | ConvertFrom-Json
$forgeExpectedFailureOutput = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot $forgeExpectedFailure.stdout)
if ($forgeExpectedFailure.exit_code -ne 1 -or $forgeExpectedFailureOutput -notmatch 'project_not_found') { throw 'The retained first-run diagnostic does not prove the resolved registry defect.' }
foreach ($forgeArtifact in $forgeEvidence.artifacts) {
  $forgeArtifactPath = Join-Path $forgeRoot ([string]$forgeArtifact.path)
  $forgeArtifactItem = Get-Item -LiteralPath $forgeArtifactPath
  if ($forgeArtifactItem.Length -ne [int64]$forgeArtifact.bytes) { throw "Artifact size mismatch: $($forgeArtifact.path)" }
  $forgeArtifactHash = (Get-FileHash -LiteralPath $forgeArtifactPath -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($forgeArtifactHash -ne [string]$forgeArtifact.sha256) { throw "Artifact hash mismatch: $($forgeArtifact.path)" }
}
foreach ($forgeSource in $forgeEvidence.source_evidence) {
  $forgeSourcePath = Join-Path $forgeRoot ([string]$forgeSource.path)
  $forgeSourceHash = (Get-FileHash -LiteralPath $forgeSourcePath -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($forgeSourceHash -ne [string]$forgeSource.sha256) { throw "Source hash mismatch: $($forgeSource.path)" }
}
$forgeGolden = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot 'tests/fixtures/Mcp/mcp-tools-semantic-golden.json') | ConvertFrom-Json
if ($forgeGolden.schemaVersion -ne 1 -or $forgeGolden.tools.Count -ne 53 -or ($forgeGolden.tools.name | Sort-Object -Unique).Count -ne 53) { throw 'The MCP golden inventory is invalid.' }
$forgePreviousName = ''
foreach ($forgeTool in $forgeGolden.tools) {
  if ($forgeTool.PSObject.Properties.Name.Count -ne 3 -or -not $forgeTool.name -or -not $forgeTool.description -or $null -eq $forgeTool.inputSchema) { throw 'A golden tool descriptor is incomplete.' }
  if ($forgePreviousName -and [string]::CompareOrdinal($forgePreviousName,[string]$forgeTool.name) -ge 0) { throw 'The MCP golden inventory is not strictly ordered.' }
  $forgePreviousName = [string]$forgeTool.name
}
$forgeTextFiles = @('CMakeLists.txt','.forge-codex/state/decisions/P14-007-alpha-stdio-persistence-ownership.md','.forge-codex/state/evidence/P14/stdio-serve-primary-fallback-snapshot-checkpoint.json','.forge-codex/state/run-state.json','include/ForgeConductor/Application/ClientPresenceLifecycle.h','src/Application/ClientPresenceLifecycle.cpp','src/Hosts/Cli/CliCompositionRoot.cpp','src/Hosts/Cli/main.cpp','src/Hosts/Cli/McpServeCompositionRoot.cpp','src/Hosts/Cli/McpServeCompositionRoot.h','tests/Application/ClientPresenceLifecycleTests.cpp','tests/Mcp/McpServeProcessSnapshotTests.cpp','tests/fixtures/Mcp/mcp-tools-semantic-golden.json')
foreach ($forgeTextRelative in $forgeTextFiles) {
  $forgeBytes = [IO.File]::ReadAllBytes((Join-Path $forgeRoot $forgeTextRelative))
  if ($forgeBytes.Length -ge 3 -and $forgeBytes[0] -eq 0xEF -and $forgeBytes[1] -eq 0xBB -and $forgeBytes[2] -eq 0xBF) { throw "UTF-8 BOM found: $forgeTextRelative" }
  $forgeText = [Text.Encoding]::UTF8.GetString($forgeBytes)
  if ([regex]::IsMatch($forgeText,'(?<!\r)\n')) { throw "Bare LF found: $forgeTextRelative" }
}
git diff --check
if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed.' }
Write-Host "P14 stdio checkpoint integrity passed: $($forgeCommands.Count) command records, $($forgeEvidence.artifacts.Count) artifacts, $($forgeEvidence.source_evidence.Count) source hashes, 53 tools."
